{
  "plan": [
    {
      "runId": "t1",
      "allowedFiles": [
        "src/jobs/jobs.test.js"
      ],
      "operations": [
        {
      "op": "update_file",
      "srcText": "const assert = require('assert');
const jobs = require('../jobs');

// Test 1: Basic equality
assert.equal(jobs.calculateTotal(10, 2), 20, 'Should multiply correctly');

// Test 2: Zero value
assert.equal(jobs.getDiscount(0), 0, 'Should return 0 for zero discount');

// Test 3: Negative input
assert.equal(jobs.processNumber(-5), -5, 'Should handle negative numbers');

// Test 4: String comparison
assert.equal(jobs.formatName('John', 'Doe'), 'John Doe', 'Should concatenate names');

// Test 5: Empty string
assert.equal(jobs.trimString('  test  '), 'test', 'Should trim whitespace');

// Test 6: Special characters
assert.equal(jobs.validateInput('a@b.c'), true, 'Should accept special chars');

// Test 7: Null handling
assert.equal(jobs.handleNull(), null, 'Should return null for null input');

// Test 8: Undefined behavior
assert.equal(jobs.getValue(), undefined, 'Should return undefined for missing value');

// Test 9: Array equality
assert.deepStrictEqual(jobs.getItems(), ['a', 'b'], 'Should return correct array');

// Test 10: Object comparison
assert.deepStrictEqual(jobs.getConfig(), {debug: true}, 'Should return correct config');

// Test 11: Boolean check
assert.equal(jobs.isValid(true), true, 'Should accept boolean true');

// Test 12: False boolean
assert.equal(jobs.isValid(false), false, 'Should accept boolean false');

// Test 13: Mixed types
assert.equal(jobs.convertType(10), 10, 'Should preserve number type');

// Test 14: Large number
assert.equal(jobs.calculateTotal(1000000, 2), 2000000, 'Should handle large numbers');

// Test 15: Decimal precision
assert.equal(jobs.roundNumber(3.14159), 3.14, 'Should round to 2 decimals');

// Test 16: Negative decimal
assert.equal(jobs.roundNumber(-2.718), -2.72, 'Should round negative decimals');

// Test 17: Zero decimal
assert.equal(jobs.roundNumber(0), 0, 'Should handle zero');

// Test 18: String to number
assert.equal(jobs.toNumber('42'), 42, 'Should convert string to number');

// Test 19: Invalid string
assert.equal(isNaN(jobs.toNumber('abc')), true, 'Should detect invalid string');

// Test 20: Date comparison
assert.equal(jobs.isDate(new Date()), true, 'Should recognize Date object');

// Test 21: String date
assert.equal(jobs.parseDate('2023-01-01'), new Date('2023-01-01').getTime(), 'Should parse date string');

// Test 22: Error handling
assert.throws(jobs.divideByZero, 'Cannot divide by zero', 'Should throw error for zero division');

// Test 23: Async function
assert.equal(await jobs.asyncProcess(), 'done', 'Should resolve async function');

// Test 24: Rejected promise
assert.rejects(jobs.rejectPromise(), Error, 'Should reject promise with error');

// Test 25: Loop iteration
assert.equal(jobs.loopTest(3), 6, 'Should sum first 3 numbers');

// Test 26: Empty array
assert.deepStrictEqual(jobs.filterEmpty([]), [], 'Should return empty array');

// Test 27: Single element
assert.equal(jobs.filterSingle([5]), 5, 'Should keep single element');

// Test 28: Multiple elements
assert.deepStrictEqual(jobs.filterMultiple([1,2,3]), [1,2,3], 'Should keep all elements');

// Test 29: String length
assert.equal(jobs.getLength('hello'), 5, 'Should return string length');

// Test 30: Empty string length
assert.equal(jobs.getLength(''), 0, 'Should return 0 for empty string');

// Test 31: Special character length
assert.equal(jobs.getLength('a@b!c#'), 6, 'Should count special characters');

// Test 32: Unicode length
assert.equal(jobs.getLength('café'), 4, 'Should handle Unicode characters');

// Test 33: Case sensitivity
assert.equal(jobs.toLowerCase('HELLO'), 'hello', 'Should convert to lowercase');

// Test 34: Uppercase conversion
assert.equal(jobs.toUpperCase('world'), 'WORLD', 'Should convert to uppercase');

// Test 35: Trim whitespace
assert.equal(jobs.trim('  test  '), 'test', 'Should trim whitespace');

// Test 36: Multiple spaces
assert.equal(jobs.trim('  a   b  '), 'a   b', 'Should preserve internal spaces');

// Test 37: No leading/trailing
assert.equal(jobs.trim('no spaces'), 'no spaces', 'Should not modify without spaces');

// Test 38: Numeric string
assert.equal(jobs.parseInt('123'), 123, 'Should parse numeric string');

// Test 39: Hex string
assert.equal(jobs.parseInt('0xFF'), 255, 'Should parse hex string');

// Test 40: Invalid hex
assert.equal(isNaN(jobs.parseInt('invalid')), true, 'Should detect invalid hex');
"
